package br.com.mikael.nexustech.gui;
import br.com.mikael.nexustech.energy.TileEntityCoalGenerator;import net.minecraft.client.gui.Gui;import net.minecraft.client.gui.inventory.GuiContainer;import net.minecraft.entity.player.InventoryPlayer;
public class GuiCoalGenerator extends GuiContainer{private final TileEntityCoalGenerator te;public GuiCoalGenerator(InventoryPlayer inv,TileEntityCoalGenerator t){super(new ContainerCoalGenerator(inv,t));te=t;xSize=176;ySize=166;}protected void drawGuiContainerForegroundLayer(int mx,int my){fontRenderer.drawString("Gerador a Carvao",8,6,0x404040);fontRenderer.drawString("Combustivel",62,20,0x404040);fontRenderer.drawString("Inventario",8,72,0x404040);fontRenderer.drawString(te.getEnergyStored()+" / "+te.getMaxEnergyStored()+" FE",8,58,0x404040);}protected void drawGuiContainerBackgroundLayer(float p,int mx,int my){drawDefaultBackground();int l=(width-xSize)/2,t=(height-ySize)/2;Gui.drawRect(l,t,l+176,t+166,0xFFC6C6C6);Gui.drawRect(l+4,t+4,l+172,t+162,0xFFE8E8E8);Gui.drawRect(l+7,t+69,l+169,t+72,0xFF555555);int b=(int)(158F*te.getEnergyStored()/te.getMaxEnergyStored());Gui.drawRect(l+9,t+70,l+9+b,t+71,0xFF55AA55);}}